import json

# Baseline versions (from original csproj files before conversion)
baseline = {
    "Api": {"System.Text.Json": "10.0.1", "Azure.Identity": "1.13.2"},
    "Worker": {"Microsoft.Extensions.Hosting": "8.0.1", "System.Text.Json": "8.0.4", "OpenTelemetry.Extensions.Hosting": "1.15.0"},
    "Shared": {"System.Text.Json": "10.0.1", "Azure.Identity": "1.11.4"},
    "Tests": {"xunit": "2.9.3", "System.Text.Json": "10.0.1"},
}

# After versions (from the centralized versions)
after = {
    "Api": {"System.Text.Json": "10.0.1", "Azure.Identity": "1.13.2"},
    "Worker": {"Microsoft.Extensions.Hosting": "8.0.1", "System.Text.Json": "10.0.1", "OpenTelemetry.Extensions.Hosting": "1.15.0"},
    "Shared": {"System.Text.Json": "10.0.1", "Azure.Identity": "1.13.2"},
    "Tests": {"xunit": "2.9.3", "System.Text.Json": "10.0.1"},
}

# Write a corrected baseline JSON
baseline_json = {"version": 1, "parameters": "", "projects": []}
for proj, pkgs in baseline.items():
    frameworks = [{"framework": "net8.0", "topLevelPackages": [{"id": k, "requestedVersion": v, "resolvedVersion": v} for k, v in pkgs.items()]}]
    baseline_json["projects"].append({"path": f"{proj}/{proj}.csproj", "frameworks": frameworks})
with open("baseline-packages.json", "w") as f:
    json.dump(baseline_json, f, indent=2)

print("Changes:")
for proj in sorted(set(list(baseline.keys()) + list(after.keys()))):
    bp = baseline.get(proj, {})
    ap = after.get(proj, {})
    for pkg in sorted(set(list(bp.keys()) + list(ap.keys()))):
        if bp.get(pkg) != ap.get(pkg):
            print(f"  {proj}: {pkg} {bp.get(pkg)} -> {ap.get(pkg)}")

print("\nUnchanged:")
for proj in sorted(baseline.keys()):
    for pkg in sorted(baseline[proj].keys()):
        if baseline[proj][pkg] == after[proj].get(pkg):
            print(f"  {proj}: {pkg} {baseline[proj][pkg]}")
